    def areIsomorphic(self, str1, str2):
        if len(str1) != len(str2):
            return False
        map1 = {}
        map2 = {}
        for c1, c2 in zip(str1, str2):
            if c1 in map1:
                if map1[c1] != c2:
                    return False
                # else, do nothing
            else:
                map1[c1] = c2
